import{_ as e,o as l,c as i,a5 as o}from"./chunks/framework.DJo0M80U.js";const k=JSON.parse('{"title":"原来React里的key这么有用！","description":"相信React用户在撸代码的日常中，一定遇到过这个报错： React中常见的未设置唯一key的报错 嗯，没错了，熟悉的配方，熟悉的报错～ 有些小伙伴看到是「Warning」也就置之不理了，有些凭经验反手给元素加上一个 key \\\\{唯一的值\\\\} 属性就迅速解决这个报错了。 不知道有。","frontmatter":{"title":"原来React里的key这么有用！","date":"2026-08-11T00:00:00.000Z","categories":["React 系统教程"],"tags":["React","Redux","前端","教程","OneNote","核心概念与组件"],"description":"相信React用户在撸代码的日常中，一定遇到过这个报错： React中常见的未设置唯一key的报错 嗯，没错了，熟悉的配方，熟悉的报错～ 有些小伙伴看到是「Warning」也就置之不理了，有些凭经验反手给元素加上一个 key \\\\{唯一的值\\\\} 属性就迅速解决这个报错了。 不知道有。","sidebarWeight":68,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/概念/原来React里的key这么有用！.md"},"headers":[],"relativePath":"posts/React系统教程/01-核心概念与组件/原来React里的key这么有用！.md","filePath":"posts/React系统教程/01-核心概念与组件/原来React里的key这么有用！.md"}'),r={name:"posts/React系统教程/01-核心概念与组件/原来React里的key这么有用！.md"};function a(g,t,n,s,c,u){return l(),i("div",null,[...t[0]||(t[0]=[o('<div><h1 id="原来react里的key这么有用" tabindex="-1">原来React里的key这么有用！ <a class="header-anchor" href="#原来react里的key这么有用" aria-label="Permalink to &quot;原来React里的key这么有用！&quot;">​</a></h1><blockquote><p>本节目标：理解“原来React里的key这么有用！”的核心思路，并能把它用于实际开发或面试表达。</p></blockquote><blockquote><p>说明：原 OneNote 中有图片引用，但图片未包含在导出目录中；本页保留了可用的文字与代码内容。 相信React用户在撸代码的日常中，一定遇到过这个报错：</p></blockquote><p>React中常见的未设置唯一key的报错 嗯，没错了，熟悉的配方，熟悉的报错～ 有些小伙伴看到是「Warning」也就置之不理了，有些凭经验反手给元素加上一个 key={唯一的值} 属性就迅速解决这个报错了。 不知道有多少小伙伴知道为什么React这么看重这个 key 属性，反正我以前凭直觉添加个唯一的id，再不济用索引就完事了。今天才明白，原来 key 这么有用，而且用好了还能避免性能问题甚至是 Bug ！</p><p><strong>Key</strong> <strong>为何而来？</strong> 在正式开始解释 key 属性之前，我得先说说React的Diffing算法。为了避免本文重心偏离及篇幅太长（喂喂喂现在篇幅也已经够长了喔 ，而且说得好像我能解释清楚Diffing算法一样 ️），我打算概括性地介绍一下这个过程： 首先检查根元素的类型。</p><ol><li>如果类型不一样，则卸载整个旧的DOM树，并重建新的DOM树。</li><li>如果类型一样，React会检查两者的属性。如果属性有改变，就更新相应的属性。</li><li>在比较完该节点后，递归地检查其子节点。默认情况下，React会同时遍历桕树和新树的子节点列表，在存在差异时则触发一个变化（mutation）。例如：</li></ol><p>&lt;ul&gt; &lt;li&gt;first&lt;/li&gt; &lt;li&gt;second&lt;/li&gt;&lt;/ul&gt; &lt;ul&gt; &lt;li&gt;first&lt;/li&gt; &lt;li&gt;second&lt;/li&gt; &lt;li&gt;third&lt;/li&gt;&lt;/ul&gt; React成功匹配两个 &lt;li&gt;first&lt;/li&gt; ，然后有成功匹配两个 &lt;li&gt;second&lt;/li&gt; ，下一步发现新树多了 &lt;li&gt;third&lt;/li&gt; ，于是插入该新的子节点。但是如果我们是这样去插入一个新的节点，性能将会降低： &lt;ul&gt; &lt;li&gt;first&lt;/li&gt; &lt;li&gt;second&lt;/li&gt;&lt;/ul&gt; &lt;ul&gt; &lt;li&gt;third&lt;/li&gt; &lt;li&gt;first&lt;/li&gt; &lt;li&gt;second&lt;/li&gt;&lt;/ul&gt; React不会按我们的预期那样将 &lt;li&gt;first&lt;/li&gt; 和 &lt;li&gt;second&lt;/li&gt; 当作是原有的子节点，它会将三个 &lt;li&gt; 都当成新的变化来更新。毕竟当数据量大了之后，这将会是一个很大的性能问题。 那么为了解决这个问题，React提出使用 <strong>key</strong> 属性来匹配旧树和新树的子节点。例如： &lt;ul&gt; &lt;li key=&quot;1&quot;&gt;first&lt;/li&gt; &lt;li key=&quot;2&quot;&gt;second&lt;/li&gt;&lt;/ul&gt; &lt;ul&gt; &lt;li key=&quot;3&quot;&gt;third&lt;/li&gt; &lt;li key=&quot;1&quot;&gt;first&lt;/li&gt; &lt;li key=&quot;2&quot;&gt;second&lt;/li&gt;&lt;/ul&gt; 这样一来，React在检查到这些子节点时，就知道key为 &quot;3&quot; 的节点是新项，而 &quot;1&quot; 和 &quot;2&quot; 是老朋友了，大家挪个位欢迎新朋友就座就好了。 <strong>Key</strong> <strong>如何设置？</strong></p><ul><li>一般来说，我们会将 key 的值设置为<strong>数据的「<strong><strong>id</strong></strong>」</strong>。例如 &lt;li key={todo.id}&gt;{todo.content}&lt;/li&gt; 。</li><li>如果没有id的话，我们可以为数据模型<strong>添加新的<strong><strong>id</strong></strong>属性</strong>，或者对部分内容进行hash处理，以生成每一项的key。PS: key 仅在它的邻项之间要求唯一，并不具有全局性哦！</li><li>再不济，我们可以用<strong>索引****index</strong>来作为key值，但是这个方法在一些情况下容易出Bug！例如说在需要重新排序时，由于组件示例的更新和复用是以它们的key为根据的，所以当我们对项目重新排序时， key 由于索引的变化也会跟着改变，而<strong>诸如非受控组件的状态却不会随之一起改变</strong>。官方给出的两个例子就能很好地说明问题：<a href="https://link.zhihu.com/?target=https%3A//reactjs.org/redirect-to-codepen/reconciliation/index-used-as-key" target="_blank" rel="noreferrer">以</a>index为key v.s. <a href="https://link.zhihu.com/?target=https%3A//reactjs.org/redirect-to-codepen/reconciliation/no-index-used-as-key" target="_blank" rel="noreferrer">以</a>id为key 。当然，如果我们将第一个例子中的 &lt;input/&gt; 改为受控组件，也可以避免这个问题（送上我改写第一个例子的<a href="https://link.zhihu.com/?target=https%3A//codepen.io/caijialinxx/pen/QWWKwVM%3Feditors%3D0010" target="_blank" rel="noreferrer">传送门</a>）。 &gt; 来自 &lt;<a href="https://zhuanlan.zhihu.com/p/87694289" target="_blank" rel="noreferrer">https://zhuanlan.zhihu.com/p/87694289</a>&gt;</li></ul></div>',1)])])}const p=e(r,[["render",a]]);export{k as __pageData,p as default};
